import{_ as a,o as t,c as o,a2 as r}from"./chunks/framework.DTdEDYjJ.js";const m=JSON.parse('{"title":"开发者工具","description":"Bot Studio 的开放协议、连接器和开发工具，包括多市场接入、跨 Bot 互通与 Bot 模板。","frontmatter":{"title":"开发者工具","description":"Bot Studio 的开放协议、连接器和开发工具，包括多市场接入、跨 Bot 互通与 Bot 模板。"},"headers":[],"relativePath":"tools.md","filePath":"tools.md"}'),n={name:"tools.md"};function h(i,e,l,p,s,d){return t(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="bot-studio-开放协议与开发者工具" tabindex="-1">Bot Studio 开放协议与开发者工具 <a class="header-anchor" href="#bot-studio-开放协议与开发者工具" aria-label="Permalink to &quot;Bot Studio 开放协议与开发者工具&quot;">​</a></h1><p>从你的接入目标出发。各工具独立维护，在对应仓库查阅适配范围与发行状态。 <a href="/openbot/development/architecture-report.html">技术架构报告</a></p><h2 id="agentapp-connector" tabindex="-1">AgentApp Connector <a class="header-anchor" href="#agentapp-connector" aria-label="Permalink to &quot;AgentApp Connector&quot;">​</a></h2><p>为自有应用的 MCP 入口生成客户端配置，准备七组智能体平台的预检和申报材料。源码和项目网站已公开，各市场审核由提交者完成。 <a href="https://github.com/Harzva/agentapp-connector" target="_blank" rel="noreferrer">仓库</a> · <a href="/openbot/development/integrate-and-publish.html">接入 Bot 与发布连接器</a></p><h2 id="anybot-connector" tabindex="-1">AnyBot Connector <a class="header-anchor" href="#anybot-connector" aria-label="Permalink to &quot;AnyBot Connector&quot;">​</a></h2><p>跨 Bot 互通的公开合约与参考 alpha，包含身份和授权、任务提交、查询、取消和回执。开发者可实现自己的后端适配器。 <a href="https://github.com/Harzva/anybot-connector" target="_blank" rel="noreferrer">仓库与规范</a></p><h2 id="awesome-bot" tabindex="-1">Awesome Bot <a class="header-anchor" href="#awesome-bot" aria-label="Permalink to &quot;Awesome Bot&quot;">​</a></h2><p>可下载的 Bot 角色模板与 Fleet 集合。开发者可读取机器可读的角色卡和发现索引。 <a href="https://github.com/Harzva/awesome-bot/blob/main/docs/agent-integration.md" target="_blank" rel="noreferrer">发现与导入</a></p><h2 id="codexhome-manager" tabindex="-1">CodexHome Manager <a class="header-anchor" href="#codexhome-manager" aria-label="Permalink to &quot;CodexHome Manager {#codexhome-manager}&quot;">​</a></h2><p>把不同的 Codex 配置、技能空间与专用智能体环境分开管理。需要在多个 <code>CODEX_HOME</code> 之间切换时，用明确的目录边界组织它们。</p><p><strong>适合你：</strong> 同时维护多个项目，希望为不同工作保留不同的智能体环境。</p><p><a href="https://github.com/Harzva/codexhome-manager" target="_blank" rel="noreferrer">访问公开仓库</a></p><h2 id="agentworkos" tabindex="-1">AgentWorkOS <a class="header-anchor" href="#agentworkos" aria-label="Permalink to &quot;AgentWorkOS {#agentworkos}&quot;">​</a></h2><p>为智能体工作区提供上下文配置的扫描、锁定、同步、检查与安装流程。把工作区约定作为可以管理的工程资料。</p><p><strong>适合你：</strong> 在多个工作区或机器之间维护 Agent 上下文，希望配置变化可检查、可重复。</p><p><a href="https://github.com/Harzva/AgentWorkOS" target="_blank" rel="noreferrer">访问公开仓库</a></p><h2 id="dsh-superterminal" tabindex="-1">DSH SuperTerminal <a class="header-anchor" href="#dsh-superterminal" aria-label="Permalink to &quot;DSH SuperTerminal {#dsh-superterminal}&quot;">​</a></h2><p>面向 DeepSeek Harness 的原生多面板终端，包含本地智能体库与 DSH 驱动的命令建议。</p><p><strong>适合你：</strong> 同时运行多个终端与智能体，希望把切换和并行工作集中起来。</p><p><a href="https://harzva.github.io/dsh-superterminal/" target="_blank" rel="noreferrer">访问产品官网</a> · <a href="https://github.com/Harzva/dsh-superterminal" target="_blank" rel="noreferrer">访问公开仓库</a></p><h2 id="回到-bot-studio" tabindex="-1">回到 Bot Studio <a class="header-anchor" href="#回到-bot-studio" aria-label="Permalink to &quot;回到 Bot Studio&quot;">​</a></h2><p>使用前先确认所选工具的安装与配置要求。</p><p><a href="/openbot/">Bot Studio 官网</a> · <a href="/openbot/development/contributing.html">参与贡献</a> · <a href="https://github.com/Harzva" target="_blank" rel="noreferrer">更多公开项目</a></p>',23)])])}const b=a(n,[["render",h]]);export{m as __pageData,b as default};
